mapper.select:
SELECT a.record_id as recordId, a.session_id as sessionId, a.name, a.email, a.ip_address as ipAddress, a.join_time as joinTime, a.leave_time as leaveTime, /* 참여시간 계산 - 실제 컬럼 대신 계산된 값 사용 */ CASE WHEN a.leave_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, a.join_time, a.leave_time) ELSE TIMESTAMPDIFF(MINUTE, a.join_time, NOW()) END as participationMinutes, /* 상태 계산 */ CASE WHEN a.leave_time IS NULL THEN '참여중' ELSE '퇴장완료' END as status, /* 세션 정보 추가 */ s.name as sessionName, s.using_dept as sessionDept, s.start_time as sessionStartTime, s.invite_link as sessionInviteLink, s.link_expiry as sessionLinkExpiry FROM attendance_record a LEFT JOIN session s ON a.session_id = s.session_id WHERE s.tenant_id = #{scTenantId}
AND a.session_id = #{scSessionId}
AND a.name LIKE CONCAT('%', #{scName}, '%')
AND a.email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(a.join_time) = #{scJoinTime}
ORDER BY a.join_time ASC
ORDER BY a.join_time DESC
LIMIT #{startRow}, #{pageSize}

SELECT /* QueryID : com.demo.proworks.attendance.selectListCountAttendanceByTenant */ COUNT(*) FROM attendance_record ar INNER JOIN session s ON ar.session_id = s.session_id WHERE s.tenant_id = #{scTenantId}
AND ar.session_id = #{scSessionId}
AND ar.name LIKE CONCAT('%', #{scName}, '%')
AND ar.email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(ar.join_time) = STR_TO_DATE(#{scJoinTime}, '%Y%m%d')

SELECT /* QueryID : com.demo.proworks.attendance.selectAttendanceForCSVByTenant */ ar.record_id as recordId, ar.session_id as sessionId, s.name as sessionName, s.using_dept as sessionDept, DATE_FORMAT(s.start_time, '%Y-%m-%d %H:%i:%s') as sessionStartTime, ar.name, ar.email, COALESCE(ar.ip_address, '') as ipAddress, DATE_FORMAT(ar.join_time, '%Y-%m-%d %H:%i:%s') as joinTime, CASE WHEN ar.leave_time IS NOT NULL THEN DATE_FORMAT(ar.leave_time, '%Y-%m-%d %H:%i:%s') ELSE '진행중' END as leaveTime, CASE WHEN ar.leave_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, ar.join_time, ar.leave_time) ELSE TIMESTAMPDIFF(MINUTE, ar.join_time, NOW()) END as participationMinutes, CASE WHEN ar.leave_time IS NULL THEN '참여중' ELSE '퇴장완료' END as status FROM attendance_record ar INNER JOIN session s ON ar.session_id = s.session_id WHERE s.tenant_id = #{scTenantId}
AND ar.session_id = #{scSessionId}
AND ar.name LIKE CONCAT('%', #{scName}, '%')
AND ar.email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(ar.join_time) = STR_TO_DATE(#{scJoinTime}, '%Y%m%d')
ORDER BY ar.join_time DESC

SELECT /* QueryID : com.demo.proworks.attendance.selectAttendanceStatsByTenant */ COUNT(*) as totalCount, SUM(CASE WHEN ar.leave_time IS NULL THEN 1 ELSE 0 END) as activeCount, SUM(CASE WHEN ar.leave_time IS NOT NULL THEN 1 ELSE 0 END) as leftCount, COALESCE(AVG( CASE WHEN ar.leave_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, ar.join_time, ar.leave_time) ELSE TIMESTAMPDIFF(MINUTE, ar.join_time, NOW()) END ), 0) as avgMinutes FROM attendance_record ar INNER JOIN session s ON ar.session_id = s.session_id WHERE s.tenant_id = #{scTenantId}
AND ar.session_id = #{scSessionId}
AND ar.name LIKE CONCAT('%', #{scName}, '%')
AND ar.email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(ar.join_time) = STR_TO_DATE(#{scJoinTime}, '%Y%m%d')

