INSERT INTO attendance_record (
record_id
 , session_id 
 , name       
 , email      
 , ip_address 
 , join_time  
 , leave_time 
) VALUES (
#{recordId}
 , #{sessionId} 
 , #{name}       
 , #{email}      
 , #{ipAddress} 
 , #{joinTime}  
 , #{leaveTime} 
)

mapper.update:
UPDATE attendance_record
SET
record_id = #{recordId}
 , session_id = #{sessionId} 
 , name = #{name}       
 , email = #{email}      
 , ip_address = #{ipAddress} 
 , join_time = #{joinTime}  
 , leave_time = #{leaveTime} 
WHERE record_id = #{recordId}

